<details class="span-two"><summary>Motorcycle compatibility rules / {{ count($selectedModelIds) }}</summary><p class="field-help">Only mark a model compatible after checking the complete package, oil pump, fittings, and product variants. Add a source or workshop record for each compatible model.</p>@foreach($vehicleModels as $vehicleModel)@php($selected = in_array($vehicleModel->id, array_map('intval', $selectedModelIds), true))<div class="service-part-config-row"><label><input type="checkbox" name="compatible_model_ids[]" value="{{ $vehicleModel->id }}" @checked($selected)>{{ $vehicleModel->brand->name }} {{ $vehicleModel->name }} · {{ $vehicleModel->category->name }}</label><label>Compatibility<select name="compatible_model_compatibility[{{ $vehicleModel->id }}]"><option value="unverified" @selected(data_get($compatibilities, $vehicleModel->id, 'unverified') === 'unverified')>Unverified</option><option value="compatible" @selected(data_get($compatibilities, $vehicleModel->id) === 'compatible')>Compatible</option><option value="incompatible" @selected(data_get($compatibilities, $vehicleModel->id) === 'incompatible')>Incompatible</option></select></label><label>Source / workshop record<input name="compatible_model_sources[{{ $vehicleModel->id }}]" value="{{ data_get($sources, $vehicleModel->id) }}" maxlength="255"></label></div>@endforeach</details>
